function _setResistMult(resistances, shortKey, mult) {
  const mapping = _RESIST_KEY_MAP[shortKey];
  if (!mapping) return;
  const [group, field] = mapping;
  if (!resistances[group]) resistances[group] = {};
  if (field === 'ohms') {
